package tf

import (
	"bytes"
	"context"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"github.com/hashicorp/terraform-exec/tfexec"
)

// BackendStubFileName is the generated file that declares which backend
// TYPE a directory uses. Terraform requires this to physically exist as
// a literal block in the module's own configuration — there's no way to
// supply the backend type purely via CLI flags, only the settings inside
// an already-declared backend can come from outside (see MigrateBackend).
// A leading dot would make Terraform ignore the file entirely (its
// config loader skips dotfiles), which is why this isn't named to match
// this project's other dotfile conventions (.manual-check, .env, ...).
const BackendStubFileName = "deploy_backend.tf"

// HasBackendStub reports whether workDir already has the generated
// backend stub — this is what "already migrated" means, and what makes
// a batch migration idempotent: already-migrated directories are
// silently skipped on a re-run. workDir is where terraform actually
// runs (see manifest.Resolver.WorkDir) — the stub is a real .tf file,
// so it has to live where Terraform will actually look for it, which
// may be a subpath within a repo's own checkout, not the repo's root.
func HasBackendStub(workDir string) bool {
	_, err := os.Stat(filepath.Join(workDir, BackendStubFileName))
	return err == nil
}

// WriteBackendStub writes the minimal backend-type declaration into
// workDir. It's the only thing that ever needs to exist there by hand
// (or rather, generated once by this) — real settings come from
// BackendConfig via -backend-config at init time (see MigrateBackend),
// not from this file. This file is deliberately meant to be committed:
// its presence, and its git history, is the record of when a directory
// was migrated and to what backend type — the actual settings can be
// read from the shared env file at any time, but "was this migrated,
// and when" is exactly the kind of thing that's easy to lose track of
// otherwise.
func WriteBackendStub(workDir, backendType string) error {
	content := fmt.Sprintf(`# Generated by "homelab-deploy init --migrate-backend". Do not hand-edit.
#
# Terraform requires the backend TYPE to be declared as a literal block
# physically inside the module's own configuration — this can't be
# supplied purely via flags. The real settings (bucket, region,
# credentials, the per-directory state location, etc.) come from the
# [backend] section of the shared/secrets env file via -backend-config
# at init time, not from this file. Commit this file: its presence (and
# git history) is the record of when this directory was migrated to a
# remote backend and to what type.

terraform {
  backend %q {}
}
`, backendType)
	return os.WriteFile(filepath.Join(workDir, BackendStubFileName), []byte(content), 0o644)
}

// RemoveBackendStub deletes the generated stub — used to roll back after
// a failed migration, so the directory is correctly treated as "not yet
// migrated" on a retry rather than silently skipped because the stub
// exists despite the migration itself never having succeeded.
func RemoveBackendStub(workDir string) error {
	err := os.Remove(filepath.Join(workDir, BackendStubFileName))
	if os.IsNotExist(err) {
		return nil
	}
	return err
}

// dirPlaceholder is substituted with a directory's own path wherever it
// appears in a [backend] setting's value — e.g. a setting of
// `key={dir}.tfstate` becomes `key=services/authentik.tfstate` for that
// directory. This is deliberately NOT a fixed setting name like "key",
// because backend types disagree on what that setting is even called:
// s3/azurerm use "key", the "local" and "consul" backends use "path",
// gcs uses "prefix", postgres uses "schema_name". Requiring the setting
// NAME to be hardcoded would either be wrong for most backend types or
// require this package to special-case every one of them. Letting the
// person put {dir} in whichever setting is actually correct for their
// backend works for any backend type, while still guaranteeing per-
// directory uniqueness is computed automatically rather than hand-typed.
const dirPlaceholder = "{dir}"

// ResolveSettings substitutes dirPlaceholder with dir in every setting
// value, returning a new map (the input is never mutated).
func ResolveSettings(settings map[string]string, dir string) map[string]string {
	resolved := make(map[string]string, len(settings))
	for k, v := range settings {
		resolved[k] = strings.ReplaceAll(v, dirPlaceholder, dir)
	}
	return resolved
}

// HasDirPlaceholder reports whether any setting value contains {dir} —
// MigrateBackend refuses to proceed without it, since otherwise every
// directory would resolve to the exact same settings and collide on the
// same state location.
func HasDirPlaceholder(settings map[string]string) bool {
	for _, v := range settings {
		if strings.Contains(v, dirPlaceholder) {
			return true
		}
	}
	return false
}

// MigrateBackend runs `terraform init` against backend (with {dir}
// already resolved for this specific directory — see ResolveSettings),
// copying dir's existing state into it non-interactively. It uses
// -force-copy (not -reconfigure — that one explicitly discards the old
// state reference rather than migrating it) — per Terraform's own
// history (hashicorp/terraform#28718), -force-copy implies
// -migrate-state, and terraform-exec exposes -force-copy but not
// -migrate-state directly, so this is both the correct choice and the
// only one available.
//
// The backend stub (WriteBackendStub) must already exist in dir before
// calling this — Terraform needs the backend type declared before init
// can read the settings this passes in.
func (r *Runner) MigrateBackend(ctx context.Context, repoRoot, dir string, backend BackendConfig, liveOut ...io.Writer) error {
	if !HasDirPlaceholder(backend.Settings) {
		return fmt.Errorf(`[backend] settings must include "%s" in whichever setting represents the state's location (e.g. key=%s.tfstate for s3, path=/state/%s.tfstate for local) — without it, every directory would resolve to the same location and collide`, dirPlaceholder, dirPlaceholder, dirPlaceholder)
	}

	client, err := r.newClient(repoRoot, dir)
	if err != nil {
		return err
	}
	var buf bytes.Buffer
	stdout := teeWriter(&buf, liveOut)
	client.SetStdout(stdout)
	client.SetStderr(stdout)

	resolved := ResolveSettings(backend.Settings, dir)
	opts := []tfexec.InitOption{tfexec.ForceCopy(true)}
	for _, k := range sortedSettingKeys(resolved) {
		opts = append(opts, tfexec.BackendConfig(fmt.Sprintf("%s=%s", k, resolved[k])))
	}

	if err := client.Init(ctx, opts...); err != nil {
		return fmt.Errorf("%w\n%s", err, buf.String())
	}
	return nil
}

// backendInitOptions returns the -backend-config options Init should pass
// for dir, or nil when none apply: no [backend] configured, or dir has not
// been migrated (no backend stub), in which case it still uses whatever
// backend its own .tf files declare. A configured [backend] without the
// {dir} placeholder is an error, for the same collision reason as
// MigrateBackend.
func (r *Runner) backendInitOptions(repoRoot, dir string) ([]tfexec.InitOption, error) {
	if r.backend.IsZero() || !HasBackendStub(r.resolveWorkDir(repoRoot, dir)) {
		return nil, nil
	}
	if !HasDirPlaceholder(r.backend.Settings) {
		return nil, fmt.Errorf(`[backend] settings must include "%s" in whichever setting represents the state's location — without it, every directory would resolve to the same location and collide`, dirPlaceholder)
	}
	resolved := ResolveSettings(r.backend.Settings, dir)
	opts := make([]tfexec.InitOption, 0, len(resolved))
	for _, k := range sortedSettingKeys(resolved) {
		opts = append(opts, tfexec.BackendConfig(fmt.Sprintf("%s=%s", k, resolved[k])))
	}
	return opts, nil
}

func sortedSettingKeys(settings map[string]string) []string {
	keys := make([]string, 0, len(settings))
	for k := range settings {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}
